class AsyncCertificates:
    def __init__(self, owner: AsyncKsef) -> None:
        self.owner = owner

    async def send_enrollment(
        self, request_payload: m.EnrollCertificateRequest
    ) -> AsyncOperation[m.CertificateEnrollmentStatusResponse]:
        response = await self.owner.api.certificates.send_enrollment(request_payload)
        return self.owner.resume_operation(
            self.owner._state("certificate", response.reference_number)
        )

    async def get_limits(self) -> m.CertificateLimitsResponse:
        return await self.owner.api.certificates.get_limits()

    async def get_enrollment_data(self) -> m.CertificateEnrollmentDataResponse:
        return await self.owner.api.certificates.get_enrollment_data()

    async def query_certificates(
        self,
        request_payload: m.QueryCertificatesRequest,
        *,
        page_size: int | None = None,
        page_offset: int | None = None,
    ) -> m.QueryCertificatesResponse:
        return await self.owner.api.certificates.query_certificates(
            request_payload, page_size=page_size, page_offset=page_offset
        )

    async def retrieve_certificate(
        self, request_payload: m.RetrieveCertificatesRequest
    ) -> m.RetrieveCertificatesResponse:
        return await self.owner.api.certificates.retrieve_certificate(request_payload)

    async def revoke_certificate(
        self, certificate_serial_number: str, request_payload: m.RevokeCertificateRequest
    ) -> None:
        await self.owner.api.certificates.revoke_certificate(
            certificate_serial_number, request_payload
        )
